39	// ─── Local helpers shared with bookings flow (kept inline to avoid cross-route imports) ──
40	function toMin(t: string): number {
41	  const [h, m] = t.split(":").map(Number);
42	  return h * 60 + m;
43	}
44	function slotsBetween(startTime: string, endTime: string): string[] {
45	  const start = toMin(startTime);
46	  const end = toMin(endTime);
47	  const out: string[] = [];
48	  for (let m = start; m < end; m += 30) {
49	    const h = String(Math.floor(m / 60)).padStart(2, "0");
50	    const mm = String(m % 60).padStart(2, "0");
51	    out.push(`${h}:${mm}`);
52	  }
53	  return out;
54	}
55	
56	const router: IRouter = Router();
57	
58	function formatGame(g: typeof gamesTable.$inferSelect, joinedCount = 0, isJoined = false, isCreator = false) {
59	  return {
60	    id: g.id,
61	    creatorName: g.creatorName,
62	    sport: g.sport,
63	    city: g.city,
64	    placeName: g.placeName,
65	    facilityId: g.facilityId,
66	    courtId: g.courtId,
67	    playersNeeded: g.playersNeeded,
68	    skillLevel: g.skillLevel,
69	    datetime: new Date(g.datetime).toISOString(),
70	    durationMinutes: g.durationMinutes,
71	    description: g.description,
72	    isPrivate: g.isPrivate,
73	    requiresApproval: g.requiresApproval,
74	    teamCount: g.teamCount,
75	    status: g.status,
76	    matchType: g.matchType,
77	    bookingId: g.bookingId ?? null,
78	    createdAt: g.createdAt.toISOString(),
79	    joinedCount,
80	    slotsLeft: Math.max(0, g.playersNeeded - joinedCount),
81	    isJoined,
82	    isCreator,
83	  };
84	}
85	
86	function formatParticipant(p: typeof gameParticipantsTable.$inferSelect) {
87	  return {
88	    id: p.id,
89	    gameId: p.gameId,
90	    userName: p.userName,
91	    team: p.team,
92	    status: p.status,
93	    joinedAt: p.joinedAt.toISOString(),
94	  };
95	}
96	
97	function formatParticipantWithId(p: typeof gameParticipantsTable.$inferSelect) {
98	  return {
99	    id: p.id,
100	    gameId: p.gameId,
101	    userId: p.userId,
102	    userName: p.userName,
103	    team: p.team,
104	    status: p.status,
105	    joinedAt: p.joinedAt.toISOString(),
106	  };
107	}
108	
109	// Look up reliability scores for a list of user IDs in one query.
110	async function getReliabilityMap(userIds: string[]): Promise<Map<string, number>> {
111	  if (userIds.length === 0) return new Map();
112	  const profiles = await db.select({ userId: userProfilesTable.userId, reliabilityScore: userProfilesTable.reliabilityScore })
113	    .from(userProfilesTable)
114	    .where(inArray(userProfilesTable.userId, userIds));
115	  return new Map(profiles.map(p => [p.userId, p.reliabilityScore ?? 100]));
116	}
117	
118	function formatDateTime(value: Date | string) {
119	  return value instanceof Date ? value.toISOString() : new Date(value).toISOString();
120	}
121	
122	// GET /games/my — games where I'm creator or participant (game history)
123	router.get("/games/my", requireAuth, async (req, res): Promise<void> => {
124	  const userId = getCurrentUserId(req)!;
125	
126	  // Games where user is a participant (joined) — targeted query
127	  const participantRows = await db
128	    .select({ gameId: gameParticipantsTable.gameId, team: gameParticipantsTable.team })
129	    .from(gameParticipantsTable)
130	    .where(and(eq(gameParticipantsTable.userId, userId), eq(gameParticipantsTable.status, "joined")));
131	  const participantGameIds = participantRows.map(r => r.gameId);
132	  const myTeamMap = new Map(participantRows.map(r => [r.gameId, r.team]));
133	
134	  // Fetch only games where user is creator OR participant — no full table scan
135	  const games = participantGameIds.length > 0
136	    ? await db.select().from(gamesTable)
137	        .where(or(eq(gamesTable.creatorUserId, userId), inArray(gamesTable.id, participantGameIds)))
138	        .orderBy(desc(gamesTable.datetime))
139	    : await db.select().from(gamesTable)
140	        .where(eq(gamesTable.creatorUserId, userId))
141	        .orderBy(desc(gamesTable.datetime));
142	
143	  if (games.length === 0) { res.json([]); return; }
144	
145	  const gameIds = games.map(g => g.id);
146	
147	  // Get participants only for these specific games
148	  const allParticipants = await db
149	    .select()
150	    .from(gameParticipantsTable)
151	    .where(and(inArray(gameParticipantsTable.gameId, gameIds), eq(gameParticipantsTable.status, "joined")));
152	  const participantsByGame = new Map<number, typeof allParticipants>();
153	  for (const p of allParticipants) {
154	    if (!participantsByGame.has(p.gameId)) participantsByGame.set(p.gameId, []);
155	    participantsByGame.get(p.gameId)!.push(p);
156	  }
157	
158	  // Get results only for these specific games
159	  const results = await db.select().from(gameResultsTable)
160	    .where(inArray(gameResultsTable.gameId, gameIds));
161	  const resultByGame = new Map(results.map(r => [r.gameId, r]));
162	
163	  // Get ELO ratings only for the relevant user IDs across these games
164	  const allUserIds = [...new Set(allParticipants.map(p => p.userId))];
165	  const ratings = allUserIds.length > 0
166	    ? await db.select().from(userRatingsTable).where(inArray(userRatingsTable.userId, allUserIds))
167	    : [];
168	  const ratingKey = (uid: string, sport: string) => `${uid}::${sport}`;
169	  const ratingMap = new Map(ratings.map(r => [ratingKey(r.userId, r.sportSlug), r.elo]));
170	
171	  // Fetch booking/court/facility info for games that have a booking
172	  const bookingGameIds = games.filter(g => g.bookingId != null).map(g => g.id);
173	  type BookingRow = {
174	    gameId: number;
175	    bookingId: number;
176	    courtId: number | null;
177	    courtName: string | null;
178	    facilityName: string | null;
179	    facilityCity: string | null;
180	    courtImageUrl: string | null;
181	    date: string | null;
182	    startTime: string | null;
183	    endTime: string | null;
184	    pricePerSlot: number | null;
185	    totalSlots: number | null;
186	  };
187	  const bookingInfoMap = new Map<number, BookingRow>();
188	  if (bookingGameIds.length > 0) {
189	    const bookingRows = await db
190	      .select({
191	        gameId: gamesTable.id,
192	        bookingId: bookingsTable.id,
193	        courtId: courtsTable.id,
194	        courtName: courtsTable.name,
195	        facilityName: facilitiesTable.name,
196	        facilityCity: facilitiesTable.city,
197	        courtImageUrl: courtsTable.imageUrl,
198	        date: bookingsTable.date,
199	        startTime: bookingsTable.startTime,
200	        endTime: bookingsTable.endTime,
201	        pricePerSlot: bookingsTable.pricePerSlot,
202	        totalSlots: bookingsTable.totalSlots,
203	      })
204	      .from(gamesTable)
205	      .innerJoin(bookingsTable, eq(gamesTable.bookingId, bookingsTable.id))
206	      .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
207	      .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
208	      .where(inArray(gamesTable.id, bookingGameIds));
209	    for (const row of bookingRows) {
210	      bookingInfoMap.set(row.gameId, {
211	        ...row,
212	        pricePerSlot: row.pricePerSlot != null ? Number(row.pricePerSlot) : null,
213	      });
214	    }
215	  }
216	
217	  const out = games.map(g => {
218	    const participants = participantsByGame.get(g.id) ?? [];
219	    const result = resultByGame.get(g.id) ?? null;
220	    const myTeam = myTeamMap.get(g.id) ?? null;
221	    const booking = bookingInfoMap.get(g.id) ?? null;
222	
223	    // Determine win/loss/draw for this user
224	    let myResult: "win" | "loss" | "draw" | null = null;
225	    if (result && result.status === "confirmed" && myTeam) {
226	      const teamWon = result.scoreTeamA > result.scoreTeamB ? "A" :
227	                      result.scoreTeamB > result.scoreTeamA ? "B" : "draw";
228	      if (teamWon === "draw") myResult = "draw";
229	      else myResult = teamWon === myTeam ? "win" : "loss";
230	    }
231	
232	    return {
233	      id: g.id,
234	      sport: g.sport,
235	      city: g.city,
236	      placeName: g.placeName,
237	      description: g.description ?? null,
238	      isPrivate: g.isPrivate,
239	      datetime: formatDateTime(g.datetime),
240	      status: g.status,
241	      matchType: g.matchType,
242	      playersNeeded: g.playersNeeded,
243	      isCreator: g.creatorUserId === userId,
244	      myTeam,
245	      myResult,
246	      bookingId: booking?.bookingId ?? null,
247	      courtId: booking?.courtId ?? null,
248	      courtName: booking?.courtName ?? null,
249	      facilityName: booking?.facilityName ?? null,
250	      facilityCity: booking?.facilityCity ?? null,
251	      courtImageUrl: booking?.courtImageUrl ?? null,
252	      date: booking?.date ?? null,
253	      startTime: booking?.startTime ?? null,
254	      endTime: booking?.endTime ?? null,
255	      pricePerSlot: booking?.pricePerSlot ?? null,
256	      totalSlots: booking?.totalSlots ?? null,
257	      result: result ? {
258	        scoreTeamA: result.scoreTeamA,
259	        scoreTeamB: result.scoreTeamB,
260	        status: result.status,
261	      } : null,
262	      participants: participants.map(p => ({
263	        userId: p.userId,
264	        userName: p.userName,
265	        team: p.team,
266	        elo: ratingMap.get(ratingKey(p.userId, g.sport)) ?? 1200,
267	      })),
268	    };
269	  });
270	
271	  res.json(out);
272	});
273	
274	// GET /games — list all open upcoming games with filters
275	router.get("/games", async (req, res): Promise<void> => {
276	  const userId = getCurrentUserId(req);
277	
278	  let rows = await db
279	    .select()
280	    .from(gamesTable)
281	    .where(and(
282	      eq(gamesTable.status, "open"),
283	      eq(gamesTable.isPrivate, false),
284	    ))
285	    .orderBy(gamesTable.datetime);
286	
287	  if (req.query.sport) rows = rows.filter(r => r.sport === req.query.sport);
288	  if (req.query.city) rows = rows.filter(r => r.city.toLowerCase() === String(req.query.city).toLowerCase());
289	  if (req.query.skillLevel) rows = rows.filter(r => r.skillLevel === req.query.skillLevel || r.skillLevel === "any");
290	
291	  // Filter out past games
292	  const now = new Date();
293	  rows = rows.filter(r => new Date(r.datetime) >= now);
294	
295	  // Attach participant counts
296	  const counts = await db
297	    .select({ gameId: gameParticipantsTable.gameId, count: sql<number>`count(*)` })
298	    .from(gameParticipantsTable)
299	    .where(eq(gameParticipantsTable.status, "joined"))
300	    .groupBy(gameParticipantsTable.gameId);
301	  const countMap = new Map(counts.map(c => [c.gameId, Number(c.count)]));
302	
303	  let joinedSet = new Set<number>();
304	  if (userId) {
305	    const mine = await db.select({ gameId: gameParticipantsTable.gameId }).from(gameParticipantsTable)
306	      .where(and(eq(gameParticipantsTable.userId, userId), eq(gameParticipantsTable.status, "joined")));
307	    joinedSet = new Set(mine.map(m => m.gameId));
308	  }
309	
310	  res.json(rows.map(g => formatGame(g, countMap.get(g.id) ?? 0, joinedSet.has(g.id), !!(userId && userId === g.creatorUserId))));
311	});
312	
313	// GET /games/:id — detail (public, but shares private games via token)
314	router.get("/games/:id", async (req, res): Promise<void> => {
315	  const id = parseInt(String(req.params.id), 10);
316	  if (isNaN(id)) { res.status(400).json({ error: "Invalid id" }); return; }
317	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, id));
318	  if (!g) { res.status(404).json({ error: "Game not found" }); return; }
319	
320	  // Private games require the invite token
321	  if (g.isPrivate && g.inviteToken !== req.query.token) {
322	    const userId = getCurrentUserId(req);
323	    if (!userId || (userId !== g.creatorUserId)) {
324	      res.status(403).json({ error: "This game is private" }); return;
325	    }
326	  }
327	
328	  const userId = getCurrentUserId(req);
329	  const isCreator = userId === g.creatorUserId;
330	
331	  const participants = await db.select().from(gameParticipantsTable)
332	    .where(and(eq(gameParticipantsTable.gameId, id), eq(gameParticipantsTable.status, "joined")))
333	    .orderBy(gameParticipantsTable.joinedAt);
334	
335	  const isJoined = userId ? participants.some(p => p.userId === userId) : false;
336	
337	  // Check if current user has a pending join request
338	  let isPending = false;
339	  if (userId && !isJoined) {
340	    const [myRow] = await db.select().from(gameParticipantsTable)
341	      .where(and(eq(gameParticipantsTable.gameId, id), eq(gameParticipantsTable.userId, userId), eq(gameParticipantsTable.status, "pending")));
342	    isPending = !!myRow;
343	  }
344	
345	  // For creator: fetch pending join requests
346	  let pendingParticipants: typeof participants = [];
347	  if (isCreator) {
348	    pendingParticipants = await db.select().from(gameParticipantsTable)
349	      .where(and(eq(gameParticipantsTable.gameId, id), eq(gameParticipantsTable.status, "pending")))
350	      .orderBy(gameParticipantsTable.joinedAt);
351	  }
352	
353	  // Fetch ELO ratings + reliability scores for participants
354	  const participantRatings = await Promise.all(
355	    participants.map(p => db.select().from(userRatingsTable)
356	      .where(and(eq(userRatingsTable.userId, p.userId), eq(userRatingsTable.sportSlug, g.sport)))
357	      .limit(1).then(rows => ({ userId: p.userId, elo: rows[0]?.elo ?? 1200 })))
358	  );
359	  const ratingMap = new Map(participantRatings.map(r => [r.userId, r.elo]));
360	  const reliabilityMap = await getReliabilityMap(participants.map(p => p.userId));
361	
362	  const gameData = formatGame(g, participants.length, isJoined, isCreator);
363	  // Expose internal user IDs only to authenticated game participants, not public visitors
364	  const isAuthenticatedParticipant = isJoined || isCreator;
365	  res.json({
366	    ...gameData,
367	    ...(isCreator && g.inviteToken ? { inviteToken: g.inviteToken } : {}),
368	    ...(isAuthenticatedParticipant ? { creatorUserId: g.creatorUserId } : {}),
369	    isPending,
370	    participants: participants.map(p => ({
371	      ...(isAuthenticatedParticipant ? formatParticipantWithId(p) : formatParticipant(p)),
372	      elo: ratingMap.get(p.userId) ?? 1200,
373	      reliabilityScore: reliabilityMap.get(p.userId) ?? 100,
374	      isOrganizer: p.userId === g.creatorUserId,
375	    })),
376	    pendingParticipants: pendingParticipants.map(p => formatParticipantWithId(p)),
377	  });
378	});
379	
380	// POST /games — create
381	router.post("/games", requireAuth, async (req, res): Promise<void> => {
382	  const userId = getCurrentUserId(req)!;
383	  const {
384	    creatorName, creatorEmail, sport, city, placeName, facilityId, courtId,
385	    playersNeeded, skillLevel, datetime, durationMinutes, description, isPrivate,
386	    matchType, requiresApproval, teamCount,
387	  } = req.body ?? {};
388	
389	  if (!creatorName || !sport || !city || !datetime) {
390	    res.status(400).json({ error: "creatorName, sport, city, datetime required" }); return;
391	  }
392	
393	  const inviteToken = isPrivate ? crypto.randomBytes(16).toString("hex") : null;
