525	router.delete("/games/:id", requireAuth, async (req, res): Promise<void> => {
526	  const id = parseInt(String(req.params.id), 10);
527	  const userId = getCurrentUserId(req)!;
528	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, id));
529	  if (!g) { res.status(404).json({ error: "Not found" }); return; }
530	  if (g.creatorUserId !== userId) { res.status(403).json({ error: "Forbidden" }); return; }
531	
532	  // ─── Single-owner cancellation claim ─────────────────────────────────────────
533	  // CAS the game into 'cancelling' so that concurrent DELETEs are rejected with 409.
534	  // Without this, a second request could race past the booking-CAS (which would
535	  // already be claimed) and delete the game while the first request's Stripe call
536	  // is still in flight, producing "game deleted but booking still confirmed and
537	  // no refund issued" if Stripe then fails and the first request rolls booking back.
538	  const originalStatus = g.status;
539	  const claimGame = await db
540	    .update(gamesTable)
541	    .set({ status: "cancelling" })
542	    .where(and(eq(gamesTable.id, id), ne(gamesTable.status, "cancelling")))
543	    .returning();
544	  if (claimGame.length === 0) {
545	    res.status(409).json({ error: "Atšaukimas jau vykdomas. Bandykite po akimirkos." });
546	    return;
547	  }
548	
549	  // ─── If a paid Korts.lt booking is linked, mirror the standard booking-cancel + refund flow ──
550	  let refundedAmount = 0;
551	  let refundPercent = 0;
552	  if (g.bookingId) {
553	    const [booking] = await db.select().from(bookingsTable).where(eq(bookingsTable.id, g.bookingId));
554	    if (booking && booking.status !== "cancelled") {
555	      const totalPriceEur = Number(booking.totalPrice);
556	      const hours = hoursBeforeStart(booking.date, booking.startTime);
557	      if (hours <= 0) {
558	        res.status(400).json({ error: "Žaidimas jau prasidėjo arba pasibaigė", code: "CANCEL_TOO_LATE" });
559	        return;
560	      }
561	      const tier = computeRefund(totalPriceEur, hours);
562	
563	      // CAS on booking status to prevent double-refund if the host clicks twice or the
564	      // sweeper races us on a still-pending booking.
565	      const claimed = await db
566	        .update(bookingsTable)
567	        .set({ status: "cancelled" })
568	        .where(and(eq(bookingsTable.id, booking.id), ne(bookingsTable.status, "cancelled")))
569	        .returning();
570	
571	      if (claimed.length > 0) {
572	        let stripeRefundId: string | null = null;
573	        if (
574	          tier.refundable &&
575	          tier.refundAmount > 0 &&
576	          booking.stripePaymentIntentId &&
577	          !booking.stripePaymentIntentId.startsWith("mock_")
578	        ) {
579	          try {
580	            const stripe = await getUncachableStripeClient();
581	            const refund = await stripe.refunds.create(
582	              {
583	                payment_intent: booking.stripePaymentIntentId,
584	                amount: Math.round(tier.refundAmount * 100),
585	                reason: "requested_by_customer",
586	              },
587	              { idempotencyKey: `cancel-game-${g.id}` },
588	            );
589	            stripeRefundId = refund.id;
590	            logger.info(
591	              { gameId: g.id, bookingId: booking.id, refundId: refund.id, amount: tier.refundAmount },
592	              "Stripe refund issued for host-cancelled game",
593	            );
594	          } catch (err) {
595	            logger.error({ err, gameId: g.id, bookingId: booking.id }, "Stripe refund failed");
596	            // Roll back BOTH booking and game status so the host can retry.
597	            // Without restoring game.status, the next attempt would 409 forever.
598	            await db
599	              .update(bookingsTable)
600	              .set({ status: booking.status })
601	              .where(eq(bookingsTable.id, booking.id));
602	            await db
603	              .update(gamesTable)
604	              .set({ status: originalStatus })
605	              .where(eq(gamesTable.id, g.id));
606	            res.status(502).json({ error: "Nepavyko grąžinti pinigų. Bandykite dar kartą." });
607	            return;
608	          }
609	        }
610	
611	        await db
612	          .update(bookingsTable)
613	          .set({ refundAmount: String(tier.refundAmount), stripeRefundId })
614	          .where(eq(bookingsTable.id, booking.id));
615	
616	        refundedAmount = tier.refundAmount;
617	        refundPercent = tier.refundPercent;
618	      }
619	    }
620	  }
621	
622	  // Collect all participants before deleting (except creator) so we can notify them.
623	  const participants = await db
624	    .select()
625	    .from(gameParticipantsTable)
626	    .where(and(eq(gameParticipantsTable.gameId, id), eq(gameParticipantsTable.status, "joined")));
627	
628	  // bookingId on games has ON DELETE SET NULL, so the booking row (now 'cancelled')
629	  // survives for refund history; participants/results/chat cascade-delete with the game.
630	  await db.delete(gamesTable).where(eq(gamesTable.id, id));
631	
632	  // Notify all joined participants that the host cancelled.
633	  const sportLabel = g.sport.replace(/_/g, " ");
634	  const gameDate = new Date(g.datetime).toLocaleDateString("lt-LT");
635	  for (const p of participants) {
636	    if (p.userId && p.userId !== userId) {
637	      await sendNotification(
638	        p.userId,
639	        "game_cancelled",
640	        "Žaidimas atšauktas",
641	        `${sportLabel} žaidimas ${gameDate} (${g.city}) buvo atšauktas organizatoriaus.`,
642	        "/matches",
643	      );
644	    }
645	  }
646	
647	  res.json({ ok: true, refundAmount: refundedAmount, refundPercent });
648	});
