854	router.delete("/games/:id/leave", requireAuth, async (req, res): Promise<void> => {
855	  const id = parseInt(String(req.params.id), 10);
856	  const userId = getCurrentUserId(req)!;
857	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, id));
858	  if (!g) { res.status(404).json({ error: "Not found" }); return; }
859	  if (g.creatorUserId === userId) {
860	    res.status(400).json({ error: "Creator cannot leave — delete the game instead" }); return;
861	  }
862	
863	  // Single-transition CAS: only flip rows that are currently `joined`. If 0 rows
864	  // updated, the user wasn't actually joined → idempotent no-op (no penalty).
865	  const flipped = await db
866	    .update(gameParticipantsTable)
867	    .set({ status: "left" })
868	    .where(and(
869	      eq(gameParticipantsTable.gameId, id),
870	      eq(gameParticipantsTable.userId, userId),
871	      eq(gameParticipantsTable.status, "joined"),
872	    ))
873	    .returning({ id: gameParticipantsTable.id });
874	
875	  if (flipped.length === 0) {
876	    // Already left (or never joined) — return idempotently without penalty.
877	    res.json({ ok: true, alreadyLeft: true }); return;
878	  }
879	
880	  // Re-open if was full
881	  if (g.status === "full") {
882	    await db.update(gamesTable).set({ status: "open" }).where(eq(gamesTable.id, id));
883	  }
884	
885	  // ─── Reliability penalty: leaving within 12h of game start costs 10 points ──
886	  const now = Date.now();
887	  const startMs = new Date(g.datetime).getTime();
888	  const hoursUntilStart = (startMs - now) / (1000 * 60 * 60);
889	  const wasActive = g.status === "open" || g.status === "full";
890	  if (wasActive && hoursUntilStart > 0 && hoursUntilStart < 12) {
891	    // Ensure a profile row exists, then decrement (clamp at 0).
892	    const [existing] = await db.select({ score: userProfilesTable.reliabilityScore })
