1472	      const [booking] = await tx.insert(bookingsTable).values({
1473	        courtId: Number(courtId),
1474	        bookerUserId: userId,
1475	        customerName: creatorName,
1476	        customerEmail: creatorEmail,
1477	        customerPhone: customerPhone ?? null,
