1599	// ─── Exported helper: apply ELO for a confirmed result (used by /verify and the auto-confirm cron) ──
1600	export async function applyResultElo(gameResultId: number): Promise<void> {
1601	  const [result] = await db.select().from(gameResultsTable).where(eq(gameResultsTable.id, gameResultId));
1602	  if (!result) return;
1603	  if (result.status === "confirmed") return; // idempotent
1604	
1605	  // Only the FIRST caller flips status (race between /verify-confirm and cron).
1606	  const flipped = await db
1607	    .update(gameResultsTable)
1608	    .set({ status: "confirmed" })
1609	    .where(and(eq(gameResultsTable.id, gameResultId), eq(gameResultsTable.status, "pending_verification")))
1610	    .returning();
1611	  if (flipped.length === 0) return; // somebody else already promoted
1612	
1613	  await db.update(gamesTable).set({ status: "completed" }).where(eq(gamesTable.id, result.gameId));
1614	
1615	  const [g] = await db.select().from(gamesTable).where(eq(gamesTable.id, result.gameId));
1616	  if (!g || g.matchType !== "rated") return;
1617	
1618	  const participants = await db.select().from(gameParticipantsTable)
1619	    .where(and(eq(gameParticipantsTable.gameId, g.id), eq(gameParticipantsTable.status, "joined")));
1620	  const teamAPlayers = participants.filter(p => p.team === "A");
1621	  const teamBPlayers = participants.filter(p => p.team === "B");
1622	  const unassigned = participants.filter(p => !p.team);
1623	  const effectiveTeamA = teamAPlayers.length ? teamAPlayers : unassigned.slice(0, Math.ceil(unassigned.length / 2));
1624	  const effectiveTeamB = teamBPlayers.length ? teamBPlayers : unassigned.slice(Math.ceil(unassigned.length / 2));
1625	
1626	  const teamAWithElo = await Promise.all(effectiveTeamA.map(async p => ({ userId: p.userId, elo: (await getOrCreateRating(p.userId, g.sport)).elo })));
1627	  const teamBWithElo = await Promise.all(effectiveTeamB.map(async p => ({ userId: p.userId, elo: (await getOrCreateRating(p.userId, g.sport)).elo })));
1628	
1629	  const winner: "A" | "B" | "draw" =
1630	    result.scoreTeamA > result.scoreTeamB ? "A" :
1631	    result.scoreTeamB > result.scoreTeamA ? "B" : "draw";
1632	  const changes = calculateTeamElo(teamAWithElo, teamBWithElo, winner);
1633	  const isDraw = winner === "draw";
1634	
1635	  for (const change of changes) {
1636	    const isOnTeamA = !!teamAWithElo.find(p => p.userId === change.userId);
1637	    const isWinner = isDraw ? false : (isOnTeamA ? winner === "A" : winner === "B");
1638	    const winsAdd = isDraw ? 0 : (isWinner ? 1 : 0);
1639	    const lossesAdd = isDraw ? 0 : (!isWinner ? 1 : 0);
1640	    const drawsAdd = isDraw ? 1 : 0;
1641	
1642	    await db.update(userRatingsTable)
1643	      .set({
1644	        elo: change.newElo,
1645	        wins: sql`${userRatingsTable.wins} + ${winsAdd}`,
1646	        losses: sql`${userRatingsTable.losses} + ${lossesAdd}`,
1647	        draws: sql`${userRatingsTable.draws} + ${drawsAdd}`,
1648	        updatedAt: new Date(),
1649	      })
1650	      .where(and(eq(userRatingsTable.userId, change.userId), eq(userRatingsTable.sportSlug, g.sport)));
1651	
1652	    await db.insert(eloHistoryTable).values({
1653	      userId: change.userId,
1654	      sportSlug: g.sport,
1655	      elo: change.newElo,
1656	      delta: change.delta,
1657	      gameId: g.id,
1658	    });
1659	
1660	    const sign = change.delta > 0 ? "+" : "";
1661	    await sendNotification(
1662	      change.userId,
1663	      "elo_update",
1664	      `ELO pasikeitė: ${sign}${change.delta}`,
1665	      `Žaidimas (${g.sport}) baigtas. Reitingas: ${change.oldElo} → ${change.newElo} (${sign}${change.delta}).`,
1666	      `/matches/${g.id}`,
1667	    );
1668	  }
1669	}
