1671	// ─── Sweepers (called from cron) ──
1672	export async function sweepStalePendingGames(): Promise<number> {
1673	  // Find games stuck in pending_payment for > 15 min (Stripe abandoned/expired).
1674	  const stale = await db.select({ id: gamesTable.id, bookingId: gamesTable.bookingId })
1675	    .from(gamesTable)
1676	    .where(and(
1677	      eq(gamesTable.status, "pending_payment"),
1678	      sql`${gamesTable.createdAt} < NOW() - INTERVAL '15 minutes'`,
1679	    ));
1680	  if (stale.length === 0) return 0;
1681	
1682	  for (const row of stale) {
1683	    if (row.bookingId) {
1684	      await db.update(bookingsTable)
1685	        .set({ status: "cancelled" })
1686	        .where(and(eq(bookingsTable.id, row.bookingId), ne(bookingsTable.status, "confirmed")));
1687	    }
1688	    await db.delete(gamesTable).where(and(eq(gamesTable.id, row.id), eq(gamesTable.status, "pending_payment")));
1689	  }
1690	  return stale.length;
1691	}
1692	
1693	export async function sweepAutoConfirmResults(): Promise<number> {
1694	  const due = await db.select({ id: gameResultsTable.id })
1695	    .from(gameResultsTable)
1696	    .where(and(
1697	      eq(gameResultsTable.status, "pending_verification"),
1698	      lt(gameResultsTable.autoConfirmAt, new Date()),
1699	    ));
1700	  for (const r of due) {
1701	    try { await applyResultElo(r.id); }
1702	    catch (err) { logger.error({ err, resultId: r.id }, "auto-confirm: applyResultElo failed"); }
1703	  }
1704	  return due.length;
1705	}
