775	            className="absolute inset-0 w-full h-full object-cover object-center"
776	          />
777	          <div className="absolute inset-0" style={{ background: "linear-gradient(to bottom, rgba(19,45,76,0.4), rgba(19,45,76,0.3), rgba(19,45,76,0.85))" }} />
778	          <div className="absolute inset-0 flex flex-col justify-end px-4 sm:px-8 pb-6 max-w-6xl mx-auto">
779	            <div className="flex items-center gap-2.5 mb-2">
